"""Connection Module"""
from __future__ import annotations
import logging
import socket
from typing import Callable

from ncclient import manager as NcclientManager
from netconf_client.connect import CallhomeManager, connect_tls
from netconf_client.ncclient import Manager as NetconfClientManager
from netconf_client.session import Session

from taf.ul.oran_mplane.core.libraries.netconf_client_wrapper import NetconfClientWrapper

from taf.ul.oran_mplane.core.libraries.ncclient_wrapper import NcclientWrapper

from taf.ul.oran_mplane.core.libraries.factory import LibrariesFactory
from taf.ul.oran_mplane.tools.utils import get_socket, get_socket_family


class Connection:
    """Connection class"""

    def __init__(self, router, logger=None):
        self.logger = logging.getLogger(__name__) if logger is None else logger
        self.logger.debug("Creating Connection object")
        self.router = router
        self.sessions: dict[str, NcclientManager | NetconfClientManager] = {}
        self.srv_socket: dict[str, Session | socket.socket] = {}
        self.connection_sockets = {}
        self.tls_session = None
        self._library_wrapper: dict[str, NcclientWrapper | NetconfClientWrapper] = {}

    @property
    def library_wrapper(self):
        """Initialize proper Library based on protocol assigned per session."""
        if not self._library_wrapper or list(self._library_wrapper) != list(self.sessions):
            self._library_wrapper = {
                session: LibrariesFactory(session_params["protocol"], self.sessions[session]).create()
                for session, session_params in self.router.items() if session in self.sessions
            }
        return self._library_wrapper

    def call_home_ssh_with_custom_timeout(self, *args, **kwds):
        """call_home_ssh_with_custom_timeout
        supported kwargs: host, port, timeout"""
        host = kwds["host"]
        port = kwds.get("port", 4334)
        timeout = kwds.get("timeout", 10)
        session = kwds.pop("session", "master_0")
        self._create_socket(address=host, session=session)
        # SO_REUSEADDR have to be used because when socket was closed once it cannot be opened second time
        # even there are no open sockets. It's strange. And occurs only after radio reset using rpc.
        self.srv_socket[session].setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        self.srv_socket[session].bind((host, port))
        self.srv_socket[session].settimeout(timeout)
        self.srv_socket[session].listen()
        # Creation of connection socket.
        sock, remote_host = self.srv_socket[session].accept()
        self.connection_sockets.update({session: sock})
        self.logger.info(f"Call Home SSH connection initiated from remote host {remote_host}")
        kwds["sock"] = sock
        return NcclientManager.connect_ssh(*args, **kwds)

    def _get_method_for_protocol(self, connection_type, connection_protocol) -> Callable:
        mapping = {
            "connect_ssh": self.connect_ssh,
            "connect_tls": self.connect_tls,
            "call_home_ssh": self.call_home_ssh,
            "call_home_tls": self.call_home_tls,
        }
        method = mapping.get(f"{connection_type}_{connection_protocol}")
        if not method:
            raise NotImplementedError(
                f"connection_type:{connection_type} connection_protocol:{connection_protocol} are not supported."
            )
        return method

    def connect(self, session: str):
        """connect method
        :param session:
        :return:
        """
        self._get_method_for_protocol("connect", self._get_protocol(session))(session)

    def call_home(self, session: str):
        """call home ssh method
        :param session:
        :return:
        """
        self._get_method_for_protocol("call_home", self._get_protocol(session))(session)

    def connect_ssh(self, session: str):
        """connect ssh method
        :param session:
        :return:
        """
        if session in self.router:
            self.sessions[session] = NcclientManager.connect(
                host=self.router[session]["host"],
                port=self.router[session]["port"],
                username=self.router[session]["username"],
                password=self.router[session]["password"],
                hostkey_verify=self.router[session].get("hostkey_verify", False),
                look_for_keys=self.router[session].get("look_for_keys", False),
                device_params=self.router[session].get("device_params", {"name": "rfsw"}),
            )
            self.logger.debug(
                f"Connect SSH established. Netconf session:{session} started with params:{self.router[session]}"
            )

    def call_home_ssh(self, session: str):
        """call home ssh method
        :param session:
        :return:
        """
        if session in self.router:
            self.sessions[session] = self.call_home_ssh_with_custom_timeout(
                host=self.router[session]["host"],
                port=self.router[session]["port"],
                username=self.router[session]["username"],
                password=self.router[session]["password"],
                timeout=self.router[session].get("timeout"),
                hostkey_verify=self.router[session].get("hostkey_verify", False),
                look_for_keys=self.router[session].get("look_for_keys", False),
                device_params=self.router[session].get("device_params", {"name": "rfsw"}),
                session=session,
            )
            self.logger.debug(
                f"Call Home SSH established. Netconf session:{session} started with params:{self.router[session]}"
            )

    def close_all_sessions(self, closing_socket_only: bool = False):
        """close_all_sessions method
        :return:
        """
        if not closing_socket_only:
            for session in self.sessions:
                self.sessions[session].close_session()
                self.logger.debug(f"Netconf session:{session} terminated.")
        self._close_socket()
        self.sessions = {}

    def close_session(self, session: str, *, closing_socket_only: bool = False) -> None:
        """Close specific NETCONF session with its all dependencies.

        :param session: NETCONF session name to terminate.
        :param closing_socket_only: Flag determines whether socket is to be closed only.
        """
        if not closing_socket_only:
            self.sessions[session].close_session()
        self._close_socket(specific_session=session)
        self.sessions.pop(session, None)

    def _close_socket_instance(self, socket_instance):
        """Closing socket."""
        try:
            # Execute shutdown only on not-closed socket. Socket is closed when file descriptor == -1
            if socket_instance.fileno() != -1:
                socket_instance.shutdown(socket.SHUT_RDWR)
        except OSError as error:
            self.logger.debug(
                f"Error occurred during close the connection socket: {error}! Server socket: {socket_instance}"
            )
        socket_instance.close()

    def _close_socket(self, specific_session: str | None = None):
        """Close all sockets (connections and server)."""
        # Source: https://docs.python.org/3/library/socket.html
        # Note: close() releases the resource associated with a connection but does not necessarily
        # close the connection immediately.
        # If you want to close the connection in a timely fashion, call shutdown() before close().
        for session in list(self.connection_sockets):
            if specific_session and session != specific_session:
                continue
            self.logger.debug("Closing connection socket.")
            self._close_socket_instance(self.connection_sockets[session])
            self.connection_sockets.pop(session, None)
            self.logger.debug(f"Connection socket ({session}) closed.")

            if srv_socket := self.srv_socket.pop(session, None):
                socket_instance = srv_socket.sock if self.router[session]["protocol"] == "tls" else srv_socket
                self.logger.debug(f"Closing server socket for session {session}.")
                self._close_socket_instance(socket_instance)
                self.logger.debug("Server socket closed.")

    def call_home_tls(self, session: str):
        """call home tls method
        :param session:
        :return:
        """
        if session in self.router:
            host = self.router[session].get("host", None)
            port = self.router[session].get("port", 4335)
            initial_timeout = self.router[session].get("initial_timeout", 120)
            general_timeout = self.router[session].get("timeout", 120)
            tls_session = CallhomeManager(port=self.router[session].get("port", 4335))
            tls_session.server_socket = socket.socket(get_socket_family(host), socket.SOCK_STREAM)
            tls_session.server_socket.bind(("", tls_session.port))
            tls_session.server_socket.listen(tls_session.backlog)
            self.srv_socket[session] = tls_session.accept_one_tls(
                keyfile=self.router[session].get("keyfile", None),
                certfile=self.router[session].get("certfile", None),
                ca_certs=self.router[session].get("ca_certs", None),
                sock=get_socket(host, port, initial_timeout, general_timeout),
                timeout=general_timeout,
                server_hostname=self.router[session].get("server_hostname")
            )
            self.sessions[session] = NetconfClientManager(self.srv_socket[session], general_timeout)
            self.logger.debug(
                f"Call Home TLS established. Netconf session:{session} started with params:{self.router[session]}"
            )

    def connect_tls(self, session: str):
        """connect tls method
        :param session:
        :return:
        """
        if session in self.router:
            host = self.router[session].get("host", None)
            port = self.router[session].get("port", 830)
            initial_timeout = self.router[session].get("initial_timeout", 120)
            general_timeout = self.router[session].get("timeout", 120)
            sock = get_socket(host, port, initial_timeout, general_timeout)
            self.srv_socket[session] = connect_tls(
                sock,
                keyfile=self.router[session].get("keyfile", None),
                certfile=self.router[session].get("certfile", None),
                ca_certs=self.router[session].get("ca_certs", None),
                server_hostname=self.router[session].get("server_hostname")
            )
            self.sessions[session] = NetconfClientManager(self.srv_socket[session], general_timeout)
            self.logger.debug(
                f"Connect TLS established. Netconf session:{session} started with params:{self.router[session]}"
            )

    def _create_socket(self, address: str, session: str = "master_0") -> None:
        """Creation of server socket.
        It's always in LISTEN state. Based on address, IPV4 (AF_INET) or IPV6 (AF_INET6) socket is created.
        :return:
        """
        address_family = socket.getaddrinfo(address, None)[0][0]
        self.logger.debug(f"Socket address family is {str(address_family)}")
        self.srv_socket[session] = socket.socket(family=address_family, type=socket.SOCK_STREAM)

    def _get_protocol(self, session: str) -> str:
        """Get protocol for specific session."""
        return self.router[session]["protocol"]
